WITH "r0" AS ( SELECT "s".* FROM "public"."article" AS "s" WHERE true AND ( "s"."author_id" = $1 ) ORDER BY "s"."id" DESC NULLS FIRST ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."title" AS "title" , coalesce( "c2"."j" , '[]'::json ) AS "comments" , "c3"."j" AS "author" ) AS "%")) ORDER BY "t0"."id" DESC NULLS FIRST ), '[]') FROM "r0" AS "t0" LEFT JOIN (WITH "r1" AS ( SELECT "s".* FROM "public"."comment" AS "s" WHERE ( "s"."article_id" ) IN (SELECT "id" FROM "r0" ) AND ( "s"."article_id" = $2 ) ) SELECT "t1"."article_id" AS "k0" , coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t1"."id" AS "id" , "t1"."body" AS "body" ) AS "%")) ), '[]') AS "j" FROM "r1" AS "t1" GROUP BY "t1"."article_id" ) AS "c2" ON true AND "c2"."k0" = "t0"."id" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t1"."id" AS "id" , "t1"."name" AS "name" , "c2"."j" AS "articles" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND "s"."id" = "t0"."author_id" AND ( ( true ) ) LIMIT 1 ) AS "t1" LEFT JOIN LATERAL (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t2"."id" AS "id" ) AS "%")) ORDER BY "t2"."id" ASC NULLS LAST ), '[]') AS "j" FROM ( SELECT "s".* FROM "public"."article" AS "s" WHERE true AND "s"."author_id" = "t1"."id" AND ( ( true ) ) ORDER BY "s"."id" ASC NULLS LAST LIMIT 2 ) AS "t2" ) AS "c2" ON true ) AS "c3" ON true
